    runTs: new Date().toISOString(),
    mode: cfg.mode,
    marketsSeen: markets.length,
    marketsEligible: ranked.length,
    marketsConsidered: ranked.map((r) => r.market),
    marketSkips: skips,
    candidatesMined: 0,
    draftsWritten: [],
    duplicatesSkipped: [],
    gateRejects: [],
    miningFailures: [],
    draftsSkippedNoSpec: noSpecMarkets,
    feedbackDrafts: [],
  };

