  report.feedbackDrafts = writeFeedbackDrafts(report, process.env.DELPHI_WALLET);

  rmSync(STAGING_DIR, { recursive: true, force: true });
  writeFileSync(join("drafts", "index.json"), JSON.stringify(report, null, 2), "utf-8");
  return report;
}

