  if (note.length > MAX_NOTE_CHARS) reasons.push(`note length: ${note.length} > ${MAX_NOTE_CHARS}`);
  if (csv.length > MAX_FILE_BYTES) reasons.push(`data.csv too large: ${csv.length}`);
  return { pass: reasons.length === 0, reasons };
