  const note = await readFile(`${draftDir}/note.md`, "utf-8");
  const csv = await readFile(`${draftDir}/data.csv`);
  const market = { resolutionCriteria: "", evidenceCutoffAt: manifest.asOf } as never;
  void market;
  void marketBaselineTimestamp;
  void composeNote;
  const reasons: string[] = [];
  const items = 1 + manifest.links.length + manifest.files.length;
  if (items > ITEM_BUDGET) reasons.push(`item budget: ${items} > ${ITEM_BUDGET}`);
  if (note.length > MAX_NOTE_CHARS) reasons.push(`note length: ${note.length} > ${MAX_NOTE_CHARS}`);
